def find_user(cursor, username: str):
    cursor.execute('SELECT * FROM users WHERE username = ?', username)
    try:
        row = cursor.fetchone()
        if row is None:
            return None
        return User(id=row[0], username=row[1], email=row[2])
    except Exception:
        raise ValueError('Database error')
